begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir fixtures/costing.inc
set local role authenticated;
select is(pg_temp.cost_policy('c5000000-0000-4000-8000-000000000201','PERCENT_NET_OF_TAX',1000)#>>'{data,status}','SAVED','immutable percent net policy');
select is(pg_temp.finance_post('MANUAL_CHARGE','120000','c5000000-0000-4000-8000-000000000301','{"tax_rate_bps":2000,"tax_inclusive":true}')#>>'{data,status}','SAVED','posted charge only recognized revenue');
select is(pg_temp.costing_read('{"charge_id":"c5000000-0000-4000-8000-000000000301"}')#>>'{data,items,0,net_revenue_minor}','100000','net revenue exact');
select is(pg_temp.costing_read('{"charge_id":"c5000000-0000-4000-8000-000000000301"}')#>>'{data,items,0,cost_status}','UNKNOWN','nontracked service explicitly unknown');
select is(pg_temp.costing_read('{"charge_id":"c5000000-0000-4000-8000-000000000301"}')#>>'{data,items,0,gross_contribution_minor}',null::text,'unknown suppresses contribution');
select is(pg_temp.costing_read('{"charge_id":"c5000000-0000-4000-8000-000000000301"}')#>>'{data,items,0,margin_bps}',null::text,'unknown suppresses margin');
select is(pg_temp.costing('{"type":"DECLARE_NO_STOCK","mutation_id":"c5000000-0000-4000-8000-000000000401","charge_id":"c5000000-0000-4000-8000-000000000301","reason":"Reviewed service record proves no stock product consumed"}')#>>'{data,status}','SAVED','explicit reviewed zero source');
select is(pg_temp.costing_read('{"charge_id":"c5000000-0000-4000-8000-000000000301"}')#>>'{data,items,0,direct_product_cost_minor}','0','known zero product cost');
select is(pg_temp.costing_read('{"charge_id":"c5000000-0000-4000-8000-000000000301"}')#>>'{data,items,0,gross_contribution_minor}','100000','known zero contributes net revenue');
select is((select count(*) from public.commission_accruals),0::bigint,'manual recorder not inferred as performer');
select is(pg_temp.finance_payment('DEPOSIT','20000','c5000000-0000-4000-8000-000000000302')#>>'{data,status}','SAVED','deposit accepted');
select is((select count(*) from public.profitability_revenue_facts),1::bigint,'deposit does not become revenue');
select is(pg_temp.finance_payment('PAYMENT','120000','c5000000-0000-4000-8000-000000000303','[{"charge_id":"c5000000-0000-4000-8000-000000000301","amount_minor":"120000"}]')#>>'{data,status}','SAVED','payment allocation accepted');
select is((select count(*) from public.profitability_revenue_facts),1::bigint,'payment does not duplicate revenue');
select is(pg_temp.finance('{"type":"REFUND","mutation_id":"c5000000-0000-4000-8000-000000000402","id":"c5000000-0000-4000-8000-000000000304","original_payment_id":"c5000000-0000-4000-8000-000000000303","amount_minor":"30000","occurred_at":"2026-10-10T12:00:00Z","reason":"Actual eligible revenue returned"}')#>>'{data,status}','SAVED','refund accepted');
set constraints profitability_refund_posted immediate;
select is(pg_temp.costing_read('{"charge_id":"c5000000-0000-4000-8000-000000000301"}')#>>'{data,items,0,net_revenue_minor}','75000','refund net cumulative ratio exact');
select is((select net_minor from public.profitability_revenue_facts where charge_id='c5000000-0000-4000-8000-000000000301'),100000::bigint,'original revenue snapshot immutable');
select is(pg_temp.cost_policy('c5000000-0000-4000-8000-000000000201','PERCENT_GROSS',2000,null,1,statement_timestamp()-interval '1 minute')->>'code','COMMISSION_RETROACTIVE_DENIED','backdating over posted revenue denied');
select throws_ok($$insert into public.commission_accruals(id) values(gen_random_uuid())$$,'42501',null,'normal direct commission insert denied');
select throws_ok($$update public.commission_accruals set amount_minor=0$$,'42501',null,'normal commission update denied');
select throws_ok($$delete from public.commission_accruals$$,'42501',null,'normal commission delete denied');
reset role;
-- Synthetic immutable earnings test isolates self privacy from staff setup.
insert into public.commission_accruals(id,organization_id,location_id,charge_id,staff_user_id,policy_id,policy_version,assignment_id,method,rate_bps,basis_minor,amount_minor,currency,eligible_at)
 select 'c5000000-0000-4000-8000-000000000601','b4000000-0000-4000-8000-000000000001','b4000000-0000-4000-8000-000000000011','c5000000-0000-4000-8000-000000000301','b4000000-0000-4000-8000-000000000023','c5000000-0000-4000-8000-000000000201',1,id,'PERCENT_NET_OF_TAX',1000,100000,10000,'TRY',statement_timestamp() from public.commission_assignments where false;
set local role authenticated;
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000024',true);
select is((select count(*) from public.stock_cost_basis_events),0::bigint,'reception cannot read acquisition cost');
select is((select count(*) from public.direct_cost_facts),0::bigint,'reception cannot read direct cost');
select is((select count(*) from public.commission_accruals),0::bigint,'reception commission denied');
select is(public.costing_snapshot('b4000000-0000-4000-8000-000000000114','b4000000-0000-4000-8000-000000000011','{"kind":"COMMISSION_ALL"}')->>'code','FORBIDDEN','reception RPC denied');
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000022',true);
select is((select count(*) from public.profitability_revenue_facts),0::bigint,'cross organization profitability denied');
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000023',true);
select is(public.costing_snapshot('b4000000-0000-4000-8000-000000000113','b4000000-0000-4000-8000-000000000011','{"kind":"COMMISSION_SELF","staff_user_id":"b4000000-0000-4000-8000-000000000021"}')->>'code','FORBIDDEN','self query cannot request another staff');
select is((select count(*) from public.stock_cost_basis_events),0::bigint,'technical access does not grant cost');
reset role;
update public.salon_memberships set status='revoked',revoked_at=statement_timestamp() where id='b4000000-0000-4000-8000-000000000111';
set local role authenticated;
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000021',true);
select is((select count(*) from public.profitability_revenue_facts),0::bigint,'revoked member cost denied');
select throws_ok($$update public.audit_events set reason='Changed'$$,'42501',null,'audit remains immutable');
select * from finish();rollback;
